/// Performs a stable merge sort on a slice of elements.
///
/// This function allocates a new `Vec<T>` containing the sorted elements.
/// It uses a classic divide-and-conquer approach with a temporary buffer.
///
/// # Complexity
/// - Time: O(n log n) in all cases (best, average, and worst).
/// - Space: O(n) auxiliary space for the temporary buffer and result vector.
///
/// # Type Constraints
/// - `T` must implement `Ord` to allow comparison.
/// - `T` must implement `Clone` to facilitate copying elements during the merge process.
pub fn merge_sort<T: Ord + Clone>(v: &[T]) -> Vec<T> {
    if v.len() <= 1 {
        return v.to_vec();
    }

    let mid = v.len() / 2;
    let left = merge_sort(&v[..mid]);
    let right = merge_sort(&v[mid..]);

    merge(&left, &right)
}

