package workerpool

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
)

// ErrPoolShutdown is returned when an operation is attempted on a shutdown pool.
var ErrPoolShutdown = errors.New("worker pool is shutdown")

// Pool represents a worker pool that executes submitted functions concurrently.
type Pool struct {
	// numWorkers is the number of worker goroutines.
	numWorkers int

	// workQueue is the channel used to submit work items.
	workQueue chan func() error

	// wg tracks the number of active workers.
	wg sync.WaitGroup

	// shutdownCh signals workers to stop.
	shutdownCh chan struct{}

	// resultsCh collects errors from workers.
	resultsCh chan error

	// closed is an atomic flag indicating if the pool is shutting down.
	closed int32

	// mu protects the resultsCh and wg during shutdown.
	mu sync.Mutex
}

// New creates a new worker pool with the specified number of workers.
// The pool starts immediately with the given number of workers.
func New(n int) (*Pool, error) {
	if n <= 0 {
		return nil, fmt.Errorf("invalid number of workers: %d", n)
	}

	p := &Pool{
		numWorkers: n,
		workQueue:  make(chan func() error, n), // Buffered to prevent blocking on submit
		shutdownCh: make(chan struct{}),
		resultsCh:  make(chan error, n),        // Buffered to prevent blocking on result collection
	}

	// Start workers
	for i := 0; i < n; i++ {
		p.wg.Add(1)
		go p.worker()
	}

	return p, nil
}

